WoWFA_Data[408233] = "یک جفت Weyrnstone احضار می‌کند؛ یکی برای متحد هدف شما و یکی برای خودتان. در هر لحظه فقط یک متحد می‌تواند Weyrnstone شما را حمل کند.\n\nدارنده می‌تواند Weyrnstone را فعال کند تا به مکان Weyrnstone دیگر منتقل شود، به شرط آن‌که در فاصلهٔ 100 یارد باشد."
WoWFA_Data[408775] = "‏Essence Burst زمان کست Eruption را به‌اندازهٔ 40% کاهش می‌دهد و آسیب آن را به‌اندازهٔ 20% افزایش می‌دهد."
WoWFA_Data[409267] = "‏Eruption 25% شانس دارد در نزدیکی شما ذره‌ای از Essence منحرف‌شده شکل دهد. متحدانی که با این ذره تماس بگیرند، یک buff تصادفی از مجموعهٔ توانایی‌های شما می‌گیرند."
WoWFA_En[409311] = "Grant an ally the gift of foresight, increasing their critical strike chance by $s1% $?s412774[and occasionally copying their damage and healing spells at $412774s1% power ][]for $410089d.\n\nAffects the nearest ally within $s2 yds, preferring damage dealers with their cooldowns active, if you do not have an ally targeted."
WoWFA_Data[409311] = "به یک متحد موهبت دوراندیشی می‌بخشد؛ شانس Critical Strike او را برای 18 ثانیه به‌اندازهٔ 3% افزایش می‌دهد$?s412774[ و گاه‌به‌گاه اسپل‌های آسیب و شفای او را با قدرت 15% کپی می‌کند][].\n\nاگر متحدی هدف نگرفته باشید، روی نزدیک‌ترین متحد در فاصلهٔ 25 یارد اثر می‌گذارد و آسیب‌زننده‌هایی که کول‌داون‌هایشان فعال است را ترجیح می‌دهد."
WoWFA_Data[409329] = "هر بار که Blistering Scales منفجر شود، برای 12 ثانیه به‌اندازهٔ 15% آسیب بیشتری وارد می‌کند؛ تا 10 بار استک می‌شود."
WoWFA_Data[409676] = "وقتی متحدان با Temporal Wounds آسیب می‌زنند، سپری به‌اندازهٔ 100% از آسیب واردشده می‌گیرند. جذب نمی‌تواند از 30% حداکثر سلامتی شما بیشتر شود."
WoWFA_Data[410253] = "‏Breath of Eons برای 10 ثانیه، سرعت حرکت دشمنان را به‌اندازهٔ 70% و سرعت حملهٔ آن‌ها را به‌اندازهٔ 50% کاهش می‌دهد."
