WoWFA_Data[410260] = "$?s403631[Breath of Eons][Deep Breath] روی اولین 3 دشمن برخوردکرده یک Eruption کست می‌کند. این Eruptionها 100% شانس دارند یک Mote of Possibility ایجاد کنند."
WoWFA_En[410261] = "Fire Breath grants the inferno's blessing for $410263d to you and a nearby ally, giving their damaging attacks and spells a high chance to deal an additional $<dmg> Fire damage."
