WoWFA_Data[444322] = "‏Obsidian Scales روی هدف شما یا 1 متحد زخمی نزدیک نیز با اثربخشی 50% اعمال می‌شود."
WoWFA_Data[444843] = "شانس Critical Strike علیه اهداف بالای 50% سلامتی، به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[444845] = "آسیب در طول زمان Fire Breath به‌اندازهٔ 30% افزایش می‌یابد. شفای در طول زمان Dream Breath به‌اندازهٔ 20% افزایش می‌یابد."
WoWFA_En[444849] = "$?c1[Hover and Deep Breath][Hover, Deep Breath, and Dream Flight] travel $s1% faster, and Hover travels $s1% further."
WoWFA_Data[444849] = "$?c1[‏Hover و Deep Breath][‏Hover، Deep Breath و Dream Flight] به‌اندازهٔ 40% سریع‌تر حرکت می‌کنند و Hover به‌اندازهٔ 40% دورتر پرواز می‌کند."
WoWFA_Data[445074] = "‏Tail Swipe و Wing Buffet دشمنان را می‌سوزانند و با خاکستر کورشان می‌کنند؛ به‌طوری که حملهٔ بعدی آن‌ها طی 4 ثانیه خطا می‌رود."
WoWFA_En[445625] = "Living Flame $?c1[and Azure Strike have $s1 extra chance to trigger Essence Burst when they critically strike.][has $s1 extra chance to trigger Essence Burst when it critically strikes.]"
WoWFA_Data[445625] = "$?c1[‏Living Flame و Azure Strike هنگام Critical Strike زدن، شانس اضافی 1 برای فعال کردن Essence Burst دارند.][‏Living Flame هنگام Critical Strike زدن، شانس اضافی 1 برای فعال کردن Essence Burst دارد.]"
WoWFA_Data[445958] = "زخم‌های شما شانس کمی دارند که بسوزند و به‌اندازهٔ 30% از آسیب دریافتی، شما را شفا دهند. این اتفاق از حملاتی که آسیب بالا وارد می‌کنند بیشتر رخ می‌دهد."
WoWFA_Data[454983] = "برد جادوهای سودمند شما 5 یارد افزایش می‌یابد."
WoWFA_Data[459120] = "‏Upheaval در مکان خود پس‌لرزه‌ای ایجاد می‌کند که 2 بار دیگر، به‌اندازهٔ 30% از آسیب آن وارد می‌کند."
WoWFA_En[459537] = "$?s403631[Breath of Eons][Deep Breath] reduces the Essence cost of your next $s1 Eruptions by $459574s1."
WoWFA_Data[459537] = "$?s403631[Breath of Eons][Deep Breath] هزینهٔ Essence 6 تا Eruption بعدی شما را به‌اندازهٔ 1 کاهش می‌دهد."
WoWFA_En[1218447] = "$?c1[Fire Breath deals its damage][Fire Breath and Dream Breath deal their damage and healing] $s1% more often."
WoWFA_Data[1218447] = "$?c1[آسیب Fire Breath][آسیب و شفای Fire Breath و Dream Breath] به‌اندازهٔ 15% پرتکرارتر وارد می‌شود."
WoWFA_Data[1219723] = "‏Disintegrate به‌اندازهٔ 25% پرتکرارتر آسیب می‌زند، اما 10% آسیب کمتری وارد می‌کند."
WoWFA_Data[1237978] = "شفای برنزی و جذب برنزی به‌اندازهٔ 15% افزایش می‌یابد."
WoWFA_Data[1239581] = "اسپل‌های Empower شما به‌اندازهٔ 10% اثربخش‌تر هستند. در حال شارژ کردن یک اسپل Empower شفابخش، نمی‌توانید به عقب پرتاب شوید."
WoWFA_Data[1241669] = "شفای Verdant Embrace به‌اندازهٔ 40% افزایش می‌یابد. علاوه بر این، دیگر باعث نمی‌شود به سمت هدف بپرید؛ در عوض، یک Dream Simulacrum به جلو می‌فرستد."
WoWFA_Data[1241704] = "‏Verdant Embrace یک شارژ اضافی به‌دست می‌آورد."
WoWFA_Data[1242031] = "کست کردن Emerald Blossom باعث می‌شود Echo بعدی شما با اثربخشی 100% روی یک متحد اضافی در فاصلهٔ 25 یارد نیز کست شود. تا 2 شارژ استک می‌شود."
WoWFA_En[1242745] = "Casting Dream Flight or Stasis increases your healing over time by $1242747s1% and causes Living Flame and Reversion to have a $1242747s2% increased chance to grant Essence Burst. Lasts $?s359816[$s2][$s3] sec.\n"
WoWFA_Data[1242745] = "کست کردن Dream Flight یا Stasis، شفای در طول زمان شما را به‌اندازهٔ 50% افزایش می‌دهد و شانس Living Flame و Reversion برای دادن Essence Burst را به‌اندازهٔ 100% افزایش می‌دهد. $?s359816[20][15] ثانیه دوام دارد."
WoWFA_Data[1250914] = "‏Motes of Possibility اکنون می‌توانند Prescience به متحدان بدهند و 10% شانس فعال شدن بیشتری دارند."
WoWFA_En[1256577] = "Essence abilities have a chance to infuse your next Reversion with the power of the Green Dragonflight, upgrading it to Merithra's Blessing:\n\n$@spellicon1256581 $@spellname1256581\n$@spelldesc1256581"
WoWFA_Data[1256577] = "توانایی‌های Essence شانس دارند Reversion بعدی شما را با قدرت Green Dragonflight آغشته کنند و آن را به Merithra's Blessing ارتقا دهند:\n\n Merithra's Blessing\nSpring a bloom of life from your target, healing them and up to 4 other allies within 30 yards for $s2. Blooms may heal your primary target multiple times if no nearby injured allies are present."
WoWFA_Data[1256682] = "‏Reversion از متحدان محافظت می‌کند و 0.5% از تمام آسیب دریافتی را معکوس کرده و به‌جای آن به آن‌ها شفا می‌دهد."
WoWFA_Data[1256689] = "شفای Dream Breath به‌اندازهٔ 60% افزایش می‌یابد و Dream Breath 100% شانس دارد Merithra's Blessing بدهد."
WoWFA_Data[1259173] = "‏Breath of Eons نسخه‌ای از شما را از آینده احضار می‌کند که در نبرد به شما کمک کند و 20 ثانیه دوام دارد. نسخهٔ تکراری شما Eruption، Fire Breath و Upheaval کست می‌کند."
WoWFA_Data[1259174] = "هر بار که Ebon Might را تمدید می‌کنید، نسخهٔ تکراری شما نیز به‌اندازهٔ 50% از مقداری که Ebon Might را تمدید کرده‌اید تمدید می‌شود."
WoWFA_Data[1259175] = "وقتی نسخهٔ تکراری شما فعال است، Ebon Might شما 75% آمار اضافی می‌دهد و Upheaval و Eruption به‌اندازهٔ 25% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[1260484] = "کول‌داون Tip the Scales به‌اندازهٔ 30 ثانیه کاهش می‌یابد."
WoWFA_En[1260647] = "Chrono Flames' maximum damage or healing is increased by $s1%, up to $<cap> Arcane."
WoWFA_Data[1260647] = "حداکثر آسیب یا شفای Chrono Flameها به‌اندازهٔ 40% افزایش می‌یابد؛ حداکثر تا $<cap> Arcane."
WoWFA_En[1260745] = "While flying during $?s403631[Breath of Eons][Deep Breath] you are assisted by a squadron of Dracthyr who assault enemies with Pyre, dealing $1236970s1 Fire damage to nearby enemies up to $s3 times."
WoWFA_Data[1260745] = "در حال پرواز در طول $?s403631[Breath of Eons][Deep Breath]، یک اسکادران از Dracthyr به شما کمک می‌کند که با Pyre به دشمنان حمله می‌کنند و تا 8 بار، $1236970s1 آسیب Fire به دشمنان نزدیک وارد می‌کنند."
WoWFA_En[1261448] = "$?c1[Mass Disintegrate][Mass Eruption] strikes $s1 additional $Ltarget:targets;."
WoWFA_Data[1261448] = "$?c1[‏Mass Disintegrate][‏Mass Eruption] به 1 هدف اضافی دیگر ضربه می‌زند."
WoWFA_Data[1261452] = "توانایی‌های Essence به‌اندازهٔ 15% آسیب اضافی وارد می‌کنند."
WoWFA_En[1264269] = "$?c1[Fire Breath gains][Dream Breath and Fire Breath gain] an additional charge."
WoWFA_Data[1264269] = "$?c1[‏Fire Breath یک شارژ اضافی به‌دست می‌آورد][‏Dream Breath و Fire Breath یک شارژ اضافی به‌دست می‌آورند]."
WoWFA_En[1264321] = "Fire Breath's damage over time lasts $s1 sec longer.$?c2[\n\nDream Breath's heal over time lasts ${$s2/1000} sec longer.][]"
WoWFA_Data[1264321] = "آسیب در طول زمان Fire Breath 4 ثانیه طولانی‌تر دوام می‌آورد.$?c2[\n\nشفای در طول زمان Dream Breath 6 ثانیه طولانی‌تر دوام می‌آورد.][]"
WoWFA_Data[1264365] = "کول‌داون Fire Breath به‌اندازهٔ 5 ثانیه کاهش می‌یابد."
WoWFA_En[1264378] = "Direct damage from Fire Breath consumes absorb shields from enemies, dealing $1264379s1 additional Spellfrost damage to them."
WoWFA_Data[1264378] = "آسیب مستقیم Fire Breath سپرهای جذب آسیب دشمنان را مصرف می‌کند و $1264379s1 آسیب Spellfrost اضافی به آن‌ها وارد می‌کند."
WoWFA_Data[1265802] = "‏Eternity Surge علاوه بر آن، یک Shattering Star به سمت هدف شما آزاد می‌کند که به‌ازای هر سطح Empower رسیده، 50% آسیب بیشتری وارد می‌کند.\n\n Shattering Star\nExhale a bolt of concentrated power from your mouth at the target for 50 Spellfrost damage."
WoWFA_Data[1265826] = "آسیب Shattering Star به‌اندازهٔ 35% افزایش می‌یابد.\n\n‏Shattering Starها به سمت تمام اهداف Eternity Surge شما بیرون داده می‌شوند."
WoWFA_En[1265867] = "Eternity Surge upgrades your next Azure Strike to Azure Sweep, damaging all nearby enemies and dealing $1265871s2% additional damage.\n\n$@spellicon1265872 $@spellname1265872\n$@spelldesc1265872"
WoWFA_Data[1265867] = "‏Eternity Surge آن Azure Strike بعدی شما را به Azure Sweep ارتقا می‌دهد که به تمام دشمنان نزدیک آسیب می‌زند و 75% آسیب اضافی وارد می‌کند.\n\n Azure Sweep\nConcentrate azure energy into your tail and sweep to release pure magic upon an enemy and nearby targets for $s2 Spellfrost damage. Damage reduced beyond 8 targets."
WoWFA_En[1265979] = "Consuming Essence Burst fires a twin flame, $?c1[striking your target for $1265980s1 Fire damage][healing your target for $1265991s1]."
WoWFA_Data[1265979] = "مصرف کردن Essence Burst، شعله‌ای دوقلو شلیک می‌کند که $?c1[به هدف شما $1265980s1 آسیب Fire وارد می‌کند][هدف شما را به‌اندازهٔ $1265991s1 شفا می‌دهد]."
WoWFA_Data[1265992] = "‏Twin Flame به حداکثر 2 هدف اضافی دیگر می‌پرد."
WoWFA_En[1265993] = "$?c1[Fire Breath has][Dream Breath and Fire Breath have] a $s1% chance to generate Essence Burst."
WoWFA_Data[1265993] = "شانس ایجاد Essence Burst برای $?c1[Fire Breath][Dream Breath و Fire Breath] برابر 50% است."
WoWFA_En[1266151] = "Deep Breath deals $?a134735[$s1% reduced][$s1% increased] damage and can be cast again within $1266165d of being used.\n\nRecall will be available after the second cast if talented."
WoWFA_Data[1266151] = "‏Deep Breath $?a134735[20% آسیب کمتر][20% آسیب بیشتر] وارد می‌کند و تا 18 ثانیه پس از استفاده می‌تواند دوباره کست شود.\n\nاگر talent شده باشد، پس از کست دوم، Recall در دسترس خواهد بود."
WoWFA_Data[1267206] = "سرعت و ارتفاع Glide به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[1268881] = "شفای Defy Fate به‌اندازهٔ 100% افزایش می‌یابد و کول‌داون آن به‌اندازهٔ 1 دقیقه کاهش می‌یابد."
WoWFA_En[1271687] = "While Dragonrage is active you gain Rising Fury every $1271783t4 sec, increasing your haste by $1271783s1%, stacking up to $1271783U times."
WoWFA_Data[1271687] = "در طول فعال بودن Dragonrage، هر 6 ثانیه یک Rising Fury می‌گیرید که Haste شما را به‌اندازهٔ 4% افزایش می‌دهد؛ تا $1271783U بار استک می‌شود."
WoWFA_En[1271788] = "When Dragonrage ends, Rising Fury persists for ${$s1/1000} sec per stack, and Dragonrage becomes Unbound Flame. Unbound Flame may be cast $1292323u times before Dragonrage finishes its cooldown.\n\n$@spellicon1292321 $@spellname1292321\n$@spelldesc1292321"
WoWFA_Data[1271788] = "وقتی Dragonrage تمام می‌شود، Rising Fury به‌ازای هر استک 4 ثانیه باقی می‌ماند و Dragonrage به Unbound Flame تبدیل می‌شود. Unbound Flame می‌تواند 4 بار، پیش از آن‌که کول‌داون Dragonrage تمام شود، کست شود.\n\n Unbound Flame\nExhale destructive flame, critically striking for $<dmg> Fire damage to your target and nearby enemies, reduced beyond $<splashCap> targets.\n\n|cFFFFFFFFCauses 1 Essence $LBurst:Bursts;.|r"
WoWFA_En[1271796] = "At $1271783U stacks of Rising Fury, all damage dealt is increased by $s1%."
WoWFA_Data[1271796] = "در $1271783U استک Rising Fury، تمام آسیب واردشده به‌اندازهٔ 8% افزایش می‌یابد."
WoWFA_Data[1291457] = "آسیب Inferno's Blessing به‌اندازهٔ 40% افزایش می‌یابد و اثرات شما که Ebon Might را تمدید می‌کنند، Inferno's Blessing را نیز تمدید می‌کنند."
WoWFA_Data[1291522] = "زمان کست Living Flame به‌اندازهٔ 0.2 ثانیه کاهش می‌یابد و وقتی کست فوری نباشد، به‌اندازهٔ 50% آسیب یا شفای بیشتری وارد می‌کند."
WoWFA_En[1291636] = "Send out a ripple of temporal energy, absorbing $s1 damage and applying Echo at $s3% effectiveness on your target and up to $s2 allies within $a1 yds."
WoWFA_Data[1291636] = "موجی از انرژی زمانی آزاد می‌کند که $s1 آسیب را جذب می‌کند و روی هدف شما و حداکثر 4 متحد در فاصلهٔ 40 یارد، Echo را با اثربخشی 30% اعمال می‌کند."
